import {PAINTS,FINISHES,STRIPES,SPOILERS,GLOWS,appearanceFor,saveAppearance,paintColor} from './customization.js';
import {CARS} from './progression.js';
import {createCarPreview} from './car-visuals.js';
const el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';if(text!==undefined)e.textContent=text;return e;};
export function renderCustomization(body,profile,car,{commit,back,notify}){
 const spec=CARS.find(c=>c.id===car);if(!spec||!profile.ownedCars.includes(car)){back();return ()=>{};}
 let draft=appearanceFor(profile,car),saved=JSON.stringify(draft),preview,closed=false;const toolbar=el('div','custom-toolbar'),backButton=el('button','','← Garage'),note=el('span','','Cosmetic · No performance change');backButton.onclick=back;toolbar.append(backButton,note);const layout=el('div','custom-layout'),visual=el('div','custom-visual'),canvas=el('canvas','custom-car'),caption=el('div','custom-caption'),state=el('small','','Loading preview…');canvas.setAttribute('aria-label','Customized '+spec.name+' preview');visual.append(canvas,caption,state);const controls=el('div','custom-controls'),buttons=[];
 function refresh(){const dirty=JSON.stringify(draft)!==saved;save.textContent=dirty?'Save style':'Saved';save.disabled=!dirty;state.textContent=dirty?'Preview · Unsaved':'Saved · Next run';caption.textContent=spec.name+' / '+PAINTS.find(p=>p.id===draft.paint).name;for(const b of buttons)b.button.setAttribute('aria-pressed',String(draft[b.key]===b.id));preview?.update(draft);}
 for(const [key,title,list] of [['paint','Paint',PAINTS],['finish','Finish',FINISHES],['stripe','Twin stripes',STRIPES],['spoiler','Spoiler',SPOILERS],['glow','Underglow',GLOWS]]){const group=el('fieldset','custom-group'),legend=el('legend','',title),row=el('div',key==='paint'?'paint-options':'style-options');group.append(legend,row);for(const item of list){const button=el('button',key==='paint'?'paint-swatch':'',key==='paint'?'':item.name);button.type='button';button.setAttribute('aria-label',title+': '+item.name);button.setAttribute('aria-pressed',String(draft[key]===item.id));if(key==='paint'){button.style.setProperty('--paint',item.color||spec.color);button.title=item.name;button.append(el('span','swatch-check','✓'));}if(item.unlock&&!profile.cosmeticUnlocks?.includes(item.unlock)){button.disabled=true;button.title='Win a championship to unlock Champion Gold';button.setAttribute('aria-label',title+': '+item.name+' · Win a championship');}button.onclick=()=>{draft={...draft,[key]:item.id};refresh();};buttons.push({button,key,id:item.id});row.append(button);}controls.append(group);}
 const footer=el('div','custom-footer'),reset=el('button','','Reset'),save=el('button','save-style','Saved');save.disabled=true;reset.onclick=()=>{draft={paint:'stock',finish:'gloss',stripe:'none',spoiler:'stock',glow:'none'};refresh();};save.onclick=()=>{const previous=appearanceFor(profile,car);saveAppearance(profile,car,draft);if(!commit()){saveAppearance(profile,car,previous);notify('Saving unavailable. Try again.');return;}saved=JSON.stringify(draft);refresh();notify('Style saved · Next run');};footer.append(reset,save);controls.append(footer);layout.append(visual,controls);body.append(toolbar,layout);refresh();
 createCarPreview(canvas,spec,draft).then(p=>{if(closed){p.dispose();return;}preview=p;refresh();}).catch(e=>{console.error(e);state.textContent='Preview unavailable · Style can still be saved';canvas.hidden=true;visual.style.background=paintColor(spec,draft);});
 return ()=>{closed=true;preview?.dispose();};
}
